const stocks = $input.all();
const items = stocks[0].json;
if (!Array.isArray(items)) throw new Error('Expected array');
// Only publish stocks with score >= 80
const qualified = items.filter(s => s.score >= 80 || s.isPass);
if (qualified.length === 0) {
  return [{ json: { message: 'No qualified stocks found' } }];
}
return qualified.map(s => ({ json: s }));

parameters.text:
=You are a professional stock research analyst at MarketBeacon Pro.

Write a detailed stock analysis article for {{ $json.symbol }} with the following data:

**Company Profile**
- Symbol: {{ $json.symbol }}
- Sector: {{ $json.sector }}
- Current Price: ₹{{ $json.price }}
- Market Cap: {{ ($json.marketCap / 10000000).toFixed(2) }} Cr
- P/E Ratio: {{ $json.peRatio }}
- 52-Week Range: ₹{{ $json.fiftyTwoWeekLow }} - ₹{{ $json.fiftyTwoWeekHigh }}

**Fundamentals**
- Return on Equity (ROE): {{ $json.returnOnEquity }}%
- ROCE: {{ $json.roce }}%
- Debt-to-Equity: {{ $json.debtToEquity }}
- Beta: {{ $json.beta }}

**Institutional Audit Score: {{ $json.auditScore }}/100**
- {{ $json.isQualified ? '✅ QUALIFIED - Passes institutional screening' : '❌ Does not pass all audit parameters' }}
- Profitability Quality: {{ $json.profitabilityQuality }}
- Balance Sheet Safety: {{ $json.balanceSheetSafety }}
- Growth Quality: {{ $json.growthQuality }}

**Strategy Signals**
Active Strategies: {{ $json.strategies.map(s => s.name).join(', ') }}
Upside Potential: {{ $json.upside }}%

Write a 1000+ word analysis article with the following sections (each as a JSON object with 'heading' and 'body'):
1. Executive Summary - Overview of the stock and why it's qualified
2. Fundamental Strength - Deep dive into ROE, ROCE, debt, sales growth
3. Institutional Audit - Explain the audit score components
4. Valuation & Technical Setup - P/E context, ABCD zones, upside
5. Key Risks to Monitor - What could derail the thesis
6. Final Verdict - Summary and strategy conclusion

Also provide:
- A compelling title (max 80 chars, don't include the company name in a redundant way)
- A meta description (120-155 chars)
- 5 key takeaways as an array of strings
- A slug (lowercase, hyphens, e.g. 'reliance-stock-analysis-june-2026')
- A read time estimate (e.g. '5 min read')

CRITICAL: Respond with ONLY valid JSON (no markdown fences, no explanation):
{
  "title": "...",
  "slug": "...",
  "meta_description": "...",
  "tag": "Analysis",
  "tag_color": "text-blue-400 bg-blue-400/10 border-blue-400/20",
  "read_time": "...",
  "key_takeaways": ["...","...","...","...","..."],
  "content": [
    {"heading": "Executive Summary", "body": "..."},
    {"heading": "Fundamental Strength", "body": "..."},
    {"heading": "Institutional Audit", "body": "..."},
    {"heading": "Valuation & Technical Setup", "body": "..."},
    {"heading": "Key Risks to Monitor", "body": "..."},
    {"heading": "Final Verdict", "body": "..."}
  ]
}
